		row: []interface{}{
			"varchar_1",
			"varchar_2",
			pgx.NullString{},
			time.Date(2000, 1, 1, 0, 0, 0, 0, time.Local),
			pgx.NullTime{},
			1,
			2,
			pgx.NullInt32{},
			time.Date(2001, 1, 1, 0, 0, 0, 0, time.Local),
