		}
		ticker.Stop()
	} else {
		for _, message := range messages {
			producer.Input() <- message
		}
	}

	<-done
	close(done)

	// TODO: Decide on a better format (or add a flag for options).
	metrics.WriteOnce(config.MetricRegistry, os.Stdout)
}

