func TestGen_BuildDocCustomDelims(t *testing.T) {
	config := &Config{
		SearchDir:          "../testdata/delims",
		MainAPIFile:        "./main.go",
		OutputDir:          "../testdata/delims/docs",
		OutputTypes:        outputTypes,
