			servo1.Move(uint8(x))
			servo2.Move(uint8(z))
			fmt.Println("Current Angle: ", servo1.CurrentAngle, ",", servo2.CurrentAngle)
		})
	}

	robot := gobot.Robot{
		Connections: []gobot.Connection{firmataAdaptor, leapAdaptor},
		Devices:     []gobot.Device{servo1, servo2, leapDriver},
