	g.Transformer(genny.Dot())
	gg.Add(g)

	lopts := &licenser.Options{
		Author: opts.Author,
		Name:   opts.License,
	}

	g, err := licenser.New(lopts)
	if err != nil {
		return gg, errors.WithStack(err)
	}
	gg.Add(g)

	ig, err := initgen.New(&initgen.Options{
		Version:     "v0.0.1",
		VersionFile: filepath.Join(opts.ShortName, "version.go"),
		MainFile:    "main.go",
		Root:        opts.Root,
	})
	if err != nil {
		return gg, errors.WithStack(err)
	}
	gg.Merge(ig)

	return gg, nil
}

