	for object, inTheEnd := iterator.Next(); inTheEnd == nil; object, inTheEnd = iterator.Next() {

		builder.setReference(object)
		boolRegister = true
		visitor.VisitExpr(where)
		if boolRegister {
			fields := s.Fields
			if s.WildCard {
